<div class="page-heading"><div><span class="eyebrow dark">Cadastro de empresas</span><h1>Leads</h1><p><?= number_format($result['total'],0,',','.') ?> registros encontrados para manutenção.</p></div><div class="heading-actions"><a class="button button-secondary" href="<?= url('/leads/spreadsheet') ?>">Planilha para JSON</a><a class="button button-secondary" href="<?= url('/leads/import') ?>">Importar JSON</a><a class="button button-primary" href="<?= url('/leads/create') ?>">+ Cadastro manual</a></div></div>
<div class="method-switch compact three-methods"><a href="<?= url('/leads/create') ?>"><span>Método 1</span><strong>Cadastro manual</strong><small>Crie ou edite uma empresa diretamente no site.</small></a><a href="<?= url('/leads/import') ?>"><span>Método 2</span><strong>Importação JSON</strong><small>Adicione várias empresas de uma só vez.</small></a><a href="<?= url('/leads/spreadsheet') ?>"><span>Método 3</span><strong>Planilha para JSON</strong><small>Converta uma planilha sem enviar dados para terceiros.</small></a></div>
<section class="panel"><div class="toolbar"><form method="get" action="<?= url('/leads') ?>" class="search-form"><input type="search" name="q" value="<?= e($search) ?>" placeholder="Buscar empresa, contato, e-mail ou telefone"><input type="hidden" name="status" value="<?= e($statusFilter) ?>"><button class="button button-secondary">Buscar</button></form><div class="filter-pills"><?php foreach([''=>'Todos','Novo'=>'Novo','Em Contato'=>'Em contato','Negociação'=>'Negociação','Contratado'=>'Contratados'] as $value=>$label): ?><a class="<?= $statusFilter===$value?'active':'' ?>" href="<?= url('/leads?status='.urlencode($value).'&q='.urlencode($search)) ?>"><?= e($label) ?></a><?php endforeach; ?></div></div>
<div class="table-wrap"><table><thead><tr><th>Empresa</th><th>Contato</th><th>Ramo</th><th>Origem</th><th>Status</th><th>Entrada</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody><?php foreach($result['items'] as $lead): ?><tr class="clickable-row" data-row-link="<?= url('/leads/view?id='.(int)$lead['id']) ?>" tabindex="0" aria-label="Visualizar <?= e($lead['nome_empresa']) ?>"><td><a class="entity-link" href="<?= url('/leads/view?id='.(int)$lead['id']) ?>"><strong><?= e($lead['nome_empresa']) ?></strong></a><small><?= e($lead['nome'] ?? 'Contato não informado') ?></small></td><td><?= e($lead['email']) ?><small><?= e($lead['telefone']) ?></small></td><td><?= e($lead['ramo_atividade']) ?></td><td><?= e($lead['origem']) ?></td><td><span class="badge <?= strtolower(str_replace(' ','-',$lead['status'])) ?>"><?= e($lead['status']) ?></span></td><td><?= date('d/m/Y',strtotime($lead['criado_em'])) ?></td><td><div class="row-actions"><a class="table-action" href="<?= url('/leads/view?id='.(int)$lead['id']) ?>">Visualizar</a><a class="table-action" href="<?= url('/leads/edit?id='.(int)$lead['id']) ?>">Editar</a></div></td></tr><?php endforeach; ?><?php if($result['items']===[]): ?><tr><td colspan="7" class="empty-state">Nenhum lead encontrado com estes filtros.</td></tr><?php endif; ?></tbody></table></div>
<div class="pagination"><span>Página <?= $result['page'] ?> · até 20 itens</span><div><?php $paginationQuery='&q='.urlencode($search).'&status='.urlencode($statusFilter); if($result['page']>1): ?><a href="<?= url('/leads?page='.($result['page']-1).$paginationQuery) ?>">Anterior</a><?php endif; ?><?php if($result['page']*$result['per_page']<$result['total']): ?><a href="<?= url('/leads?page='.($result['page']+1).$paginationQuery) ?>">Próxima</a><?php endif; ?></div></div></section>
